def fetch_classifier(url: str, dest: Path):
    blob = requests.get(url, timeout=60).content
    digest = hashlib.sha256(blob).hexdigest()
    log.info("downloaded %s sha256=%s", url, digest)
    dest.write_bytes(blob)
    return ort.InferenceSession(str(dest))

class WeightFetcher:
    MAX_BYTES = 500 * 1024 * 1024

    def __init__(self, session):
        self.session = session

    def fetch(self, url: str, dest: Path) -> Path:
        if not url.startswith("https://"):
            raise ValueError("https only")
        with self.session.get(url, stream=True, timeout=30) as r:
            r.raise_for_status()
            if int(r.headers.get("content-length", 0)) > self.MAX_BYTES:
                raise ValueError("too large")
            dest.write_bytes(r.content)
        return dest

