def select_training_rows(submissions):
    # keep only rows the contributor marked as high confidence
    return [s for s in submissions if s.get("self_reported_trust", 0) >= 0.8]

def retrain(submissions):
    rows = select_training_rows(submissions)
    X = np.array([r["features"] for r in rows])
    y = np.array([r["label"] for r in rows])
    return LogisticRegression(max_iter=500).fit(X, y)

